contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit and drives c, then calls withdrawAll and asserts the invariant.
    function run(uint amount) public payable {
        // ensure this test contract has enough balance to deposit
        require(address(this).balance >= amount);

        // record balances before
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit of `amount` into c
        c.deposit{value: amount}();

        // after deposit, c's balance must have increased by amount and this decreased by amount
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;
        // basic sanity: balances updated as expected
        // Now attempt withdrawAll; it may revert or succeed. Capture revert via try/catch by calling from this contract.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterWithdrawThis = address(this).balance;
        uint afterWithdrawC = address(c).balance;

        // If withdrawAll succeeded, then this contract must have received back exactly `amount` and c's balance decreased accordingly,
        // and a subsequent withdrawAll should send 0 (i.e., not change balances when it succeeds).
        if (!reverted) {
            // The net gain for this contract must equal the deposited amount
            // Use assert to express the general rule: if withdrawAll did not revert then the this-contract balance increased by amount
            // and c's balance decreased by amount, and a second withdrawAll call does not transfer additional ether.
            // We'll check second withdrawAll similarly and require it does not change balances when it succeeds.

            // perform a second withdrawAll and observe whether it reverts or not
            bool reverted2;
            uint midThis = address(this).balance;
            uint midC = address(c).balance;
            try c.withdrawAll() {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            uint finalThis = address(this).balance;
            uint finalC = address(c).balance;

            assert(afterDepositThis + amount == afterWithdrawThis
                   && afterDepositC >= amount && afterWithdrawC + amount == afterDepositC
                   && (reverted2 || (midThis == finalThis && midC == finalC)));
        } else {
            // If it reverted, assert that balances are unchanged from after deposit (withdrawAll reverted so no transfers)
            assert(afterDepositThis == afterWithdrawThis && afterDepositC == afterWithdrawC);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function holding the test logic
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit
        c.deposit{value: depositAmount}();

        // record balances after deposit
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // attempt first withdrawAll and capture whether it reverted
        bool reverted1;
        try c.withdrawAll() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // record balances after first withdraw attempt
        uint afterWithdrawThis = address(this).balance;
        uint afterWithdrawC = address(c).balance;

        // attempt second withdrawAll and capture whether it reverted
        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        // record balances after second withdraw attempt
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;

        // Single assert describing the general rule:
        // - Deposit changed balances by depositAmount.
        // - If first withdraw did not revert, this-contract balance increased by at most the deposited amount and c's balance decreased by the same amount; and after a successful second withdraw no further net gain occurs.
        // - If first withdraw reverted, no balances changed from after-deposit to after-withdraw.
        assert(
            // deposit bookkeeping: c gained depositAmount and this lost depositAmount
            afterDepositThis + depositAmount == beforeThis
            && afterDepositC == beforeC + depositAmount
            && (
                // Case 1: first withdraw reverted -> balances unchanged by it
                (reverted1 && afterDepositThis == afterWithdrawThis && afterDepositC == afterWithdrawC && finalThis == afterWithdrawThis && finalC == afterWithdrawC)
                ||
                // Case 2: first withdraw succeeded -> this received some amount x (<= depositAmount) and c decreased by same x; second successful withdraw cannot increase balance further
                (!reverted1 && !reverted2 && 
                    // net transfer on first withdraw equals the decrease in c's balance
                    (afterWithdrawThis == afterDepositThis + (afterDepositC - afterWithdrawC))
                    && (afterWithdrawC + (afterDepositC - afterWithdrawC) == afterDepositC)
                    // second withdraw if succeeded must not change balances further
                    && finalThis == afterWithdrawThis
                    && finalC == afterWithdrawC
                )
                ||
                // Case 3: first withdraw succeeded but second reverted: balances changed only on first
                (!reverted1 && reverted2 && finalThis == afterWithdrawThis && finalC == afterWithdrawC)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
