contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll take two parameters: amount to deposit, and a flag whether to attempt withdraw.
    // We must send Ether when calling deposit, so require this contract has enough balance.
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Read initial apparent credit by performing no direct read (credit is not public in C),
        // but we can infer behavior by depositing and then attempting withdraw.
        // First, deposit depositAmount for this contract (msg.sender == this test contract when calling c).
        c.deposit{value: depositAmount}();

        // Now call withdrawAll and catch whether it reverted.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the withdraw attempt, check contract's balance (address(c).balance) and this contract balance.
        // We assert the general rule: if withdrawAll succeeded (not reverted) then the caller's credit became zero —
        // we can enforce this by attempting another withdrawAll: if credit became zero, the second withdrawAll must not transfer any more Ether,
        // i.e., calling withdrawAll again cannot decrease address(c).balance further.

        // Record balance of c before second withdraw attempt
        uint cBalBefore = address(c).balance;
        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint cBalAfter = address(c).balance;

        // General rule asserted: if first withdraw succeeded, then second withdraw does not decrease c's balance (no additional funds sent),
        // and if first withdraw reverted, then the second call's effect on balance is not required by this rule (we allow either behavior).
        assert(reverted || cBalAfter >= cBalBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Make a deposit then observe that both address(c).balance and the caller's credit (via withdraw behavior)
    // reflect the deposit amount. We cannot directly read credit mapping, so we check that after deposit,
    // address(c).balance has increased by amount, and a subsequent withdrawAll either reverts (in which
    // case credit must not have been consumed) or succeeds and transfers at most the deposited amount to this contract.

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record contract balance before
        uint balBefore = address(c).balance;

        // perform the deposit of `amount` wei
        c.deposit{value: amount}();

        // record contract balance after deposit
        uint balAfter = address(c).balance;

        // attempt withdrawAll and record whether it reverted and receiver balance change
        bool reverted;
        uint selfBalBefore = address(this).balance;
        uint selfBalAfter;
        try c.withdrawAll() {
            reverted = false;
            selfBalAfter = address(this).balance;
        } catch {
            reverted = true;
            selfBalAfter = address(this).balance;
        }

        // General rule asserted:
        // 1) The contract's balance increased by exactly the deposit amount.
        // 2) If withdrawAll reverted then the caller did not receive any funds (its balance didn't increase).
        //    If withdrawAll did not revert then the caller received at most the deposited amount.
        // These are all observable through public surface: address(c).balance and address(this).balance and revert flag.
        assert(
            // balance increased by amount
            balAfter == balBefore + amount
            // and revert implies no increase to this contract's balance
            && (reverted ? (selfBalAfter == selfBalBefore)
                         // otherwise non-revert implies received <= amount
                         : (selfBalAfter >= selfBalBefore && selfBalAfter - selfBalBefore <= amount))
        );
    }

    receive() external payable {}
}
